package cn.blockforge.generated.generatedmod.client;

import cn.blockforge.generated.generatedmod.client.realmflight.MeteorBloomRenderer;
import com.mojang.blaze3d.systems.RenderSystem;
import org.lwjgl.opengl.GL33;

/** Exact periodic lattice gradients, generated by the same GPU hash as the field.
 * Only gradients are cached: interpolation, octaves, flow and 128 ray samples remain live. */
public final class HuahongVolumeNoiseCache {
    private static int texture;
    private static String source;
    private static boolean attempted;
    private static String status="Not generated";
    public static int texture(){return texture;}
    public static String status(){return status;}
    public static void release(){destroy();attempted=false;}
    private static void destroy(){if(texture!=0){GL33.glDeleteTextures(texture);texture=0;}}
    public static void ensure(){if(!attempted&&source!=null)reload(source);}
    public static void reload(String source){
        destroy();HuahongVolumeNoiseCache.source=source;attempted=true;int vaoBefore=GL33.glGetInteger(GL33.GL_VERTEX_ARRAY_BINDING),programBefore=GL33.glGetInteger(GL33.GL_CURRENT_PROGRAM);
        boolean srgb=GL33.glIsEnabled(GL33.GL_FRAMEBUFFER_SRGB),dither=GL33.glIsEnabled(GL33.GL_DITHER);
        int v=0,f=0,program=0,vao=0,fbo=0;
        try(var saved=new MeteorBloomRenderer.State()){
            int start=source.indexOf("vec3 hh_hash33_direct("),end=source.indexOf("vec3 hh_hash33(",start);
            if(start<0||end<0)throw new IllegalStateException("Missing direct lattice hash");
            String fragment="#version 150\n"+source.substring(start,end)+"\nout vec4 fragColor;void main(){"
                    +"int n=int(gl_FragCoord.x)+int(gl_FragCoord.y)*512;"
                    +"vec3 p=vec3(n%64,(n/64)%64,n/4096);fragColor=vec4(hh_hash33_direct(p),1.);}";
            v=compile(GL33.GL_VERTEX_SHADER,"#version 150\nvoid main(){vec2 p=vec2((gl_VertexID<<1)&2,gl_VertexID&2);gl_Position=vec4(p*2.-1.,0,1);}");
            f=compile(GL33.GL_FRAGMENT_SHADER,fragment);program=GL33.glCreateProgram();GL33.glAttachShader(program,v);GL33.glAttachShader(program,f);GL33.glLinkProgram(program);
            if(GL33.glGetProgrami(program,GL33.GL_LINK_STATUS)==0)throw new IllegalStateException(GL33.glGetProgramInfoLog(program));
            texture=GL33.glGenTextures();RenderSystem.bindTexture(texture);
            GL33.glTexImage2D(GL33.GL_TEXTURE_2D,0,GL33.GL_RGBA32F,512,512,0,GL33.GL_RGBA,GL33.GL_FLOAT,0L);
            GL33.glTexParameteri(GL33.GL_TEXTURE_2D,GL33.GL_TEXTURE_MIN_FILTER,GL33.GL_NEAREST);GL33.glTexParameteri(GL33.GL_TEXTURE_2D,GL33.GL_TEXTURE_MAG_FILTER,GL33.GL_NEAREST);
            GL33.glTexParameteri(GL33.GL_TEXTURE_2D,GL33.GL_TEXTURE_WRAP_S,GL33.GL_CLAMP_TO_EDGE);GL33.glTexParameteri(GL33.GL_TEXTURE_2D,GL33.GL_TEXTURE_WRAP_T,GL33.GL_CLAMP_TO_EDGE);
            fbo=GL33.glGenFramebuffers();GL33.glBindFramebuffer(GL33.GL_FRAMEBUFFER,fbo);GL33.glFramebufferTexture2D(GL33.GL_FRAMEBUFFER,GL33.GL_COLOR_ATTACHMENT0,GL33.GL_TEXTURE_2D,texture,0);
            if(GL33.glCheckFramebufferStatus(GL33.GL_FRAMEBUFFER)!=GL33.GL_FRAMEBUFFER_COMPLETE)throw new IllegalStateException("Gradient FBO incomplete");
            RenderSystem.disableBlend();RenderSystem.disableDepthTest();RenderSystem.disableCull();RenderSystem.disableScissor();RenderSystem.colorMask(true,true,true,true);
            GL33.glDisable(GL33.GL_FRAMEBUFFER_SRGB);GL33.glDisable(GL33.GL_DITHER);GL33.glDisable(GL33.GL_STENCIL_TEST);
            RenderSystem.viewport(0,0,512,512);GL33.glUseProgram(program);vao=GL33.glGenVertexArrays();GL33.glBindVertexArray(vao);GL33.glDrawArrays(GL33.GL_TRIANGLES,0,3);
            status="64^3 exact GPU gradients / RGBA32F / 4 MiB";
        }catch(RuntimeException failure){destroy();status="Direct hash fallback: "+failure.getMessage();}
        finally{
            if(fbo!=0)GL33.glDeleteFramebuffers(fbo);if(vao!=0)GL33.glDeleteVertexArrays(vao);GL33.glBindVertexArray(vaoBefore);
            if(program!=0)GL33.glDeleteProgram(program);if(v!=0)GL33.glDeleteShader(v);if(f!=0)GL33.glDeleteShader(f);
            GL33.glUseProgram(programBefore);
            if(srgb)GL33.glEnable(GL33.GL_FRAMEBUFFER_SRGB);else GL33.glDisable(GL33.GL_FRAMEBUFFER_SRGB);
            if(dither)GL33.glEnable(GL33.GL_DITHER);else GL33.glDisable(GL33.GL_DITHER);
        }
    }
    private static int compile(int type,String text){int shader=GL33.glCreateShader(type);GL33.glShaderSource(shader,text);GL33.glCompileShader(shader);if(GL33.glGetShaderi(shader,GL33.GL_COMPILE_STATUS)==0){String error=GL33.glGetShaderInfoLog(shader);GL33.glDeleteShader(shader);throw new IllegalStateException(error);}return shader;}
    private HuahongVolumeNoiseCache(){}
}
